export function addItem(cart: Cart, sku: string, quantity: number): Cart {
  const key = sku.toLowerCase();
  // Fix for the duplicate line bug: previously adding "abc-1" after "ABC-1"
  // created a second cart line. SKUs are case-insensitive, so we now match
  // lines on the lowercased SKU instead of the raw string.
  const existing = cart.lines.find((line) => line.sku.toLowerCase() === key);
  if (existing) {
    existing.quantity += quantity;
    return cart;
  }
  cart.lines.push({ sku, quantity });
  return cart;
}
